const feeds = [
  { url: 'https://rss.indeed.com/rss?q=engineer&l=Saudi+Arabia', source: 'indeed-eng' },
  { url: 'https://rss.indeed.com/rss?q=sales+OR+admin+OR+customer+service&l=Saudi+Arabia', source: 'indeed-general' }
];
return feeds.map((f) => ({ json: f }));

let count = 0;
try { for (const r of $('Fetch RSS').all()) { const j = r.json || {}; if ((j.title || '') && (j.link || j.guid || '')) count++; } } catch (e) {}
return [{ json: { has_rss: count > 0, rss_count: count } }];

const e = $json || {};
const wf = (e.workflow && e.workflow.name) ? e.workflow.name : 'Automated Job Applier';
const ex = (e.execution && e.execution.id) ? String(e.execution.id) : '';
let node = ''; let msg = '';
try { node = e.execution.lastNodeExecuted || ''; } catch (x) {}
try { msg = (e.execution.error && (e.execution.error.message || e.execution.error.description)) || ''; } catch (x) {}
if (!msg) { try { msg = e.error.message || ''; } catch (x) {} }
return [{ json: { workflow_name: wf, execution_id: ex, node_name: node || 'unknown', error_message: String(msg || 'Unknown error').slice(0, 900), occurred_at: new Date().toISOString(), tg: '\u26a0\ufe0f Automated Job Applier error in node "' + (node||'unknown') + '": ' + String(msg||'Unknown error').slice(0,300) + ' (exec ' + ex + ')' } }];

const rows = $input.all().map(i => i.json || {}).filter(r => r && Object.keys(r).length > 0);
const now = Date.now();
const weekAgo = now - 7*24*60*60*1000;
function ts(r){ const d = r.processed_at || r.date_added; const p = d ? Date.parse(d) : NaN; return isNaN(p) ? null : p; }
const wk = rows.filter(r => { const t = ts(r); return t !== null && t >= weekAgo; });
const byStatus = {};
for (const r of wk) { const s = String(r.status || 'unknown'); byStatus[s] = (byStatus[s]||0)+1; }
const sent = (byStatus['sent']||0);
const blocked = (byStatus['blocked_scam']||0) + (byStatus['flagged_for_review']||0);
const nu = (byStatus['new']||0);
const statusLines = Object.keys(byStatus).sort().map(k => '  - ' + k + ': ' + byStatus[k]).join('\n');
const date = new Date().toISOString().slice(0,10);
const msg = '\ud83d\udcca Automated Job Applier \u2014 Weekly Report (' + date + ')\n\n' +
  'Jobs touched this week: ' + wk.length + '\n' +
  'Applications sent: ' + sent + '\n' +
  'Blocked/flagged (ghost/scam): ' + blocked + '\n' +
  'Still queued (new): ' + nu + '\n\n' +
  'By status:\n' + (statusLines || '  (no activity)') + '\n\n' +
  'Total rows in table: ' + rows.length;
return [{ json: { chat_id: '8890901423', message: msg } }];

const stripHtml = (s) => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/\s+/g, ' ').trim();
const out = [];
function pushJob(title, company, desc, loc, url, source) {
  if (!title || !url) return false;
  const cleanDesc = stripHtml(desc) || ('Position: ' + title + '. Full details via the original listing.');
  out.push({ json: { job_title: String(title).trim(), company: (String(company || 'Unknown').trim() || 'Unknown'), job_description: cleanDesc, location: (String(loc || 'Saudi Arabia').trim() || 'Saudi Arabia'), job_url: String(url).trim(), contact_email: '', status: 'new', job_type: 'general', industry: 'General', _source: source } });
  return true;
}
function readResp(nodeName) {
  try { const f = $(nodeName).first(); return (f && f.json) ? f.json : {}; } catch (e) { return {}; }
}
try {
  const resp = readResp('Fetch Jobicy');
  const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
  let n = 0;
  for (const jb of jobs) { if (pushJob(jb.jobTitle, jb.companyName, jb.jobExcerpt || jb.jobDescription, jb.jobGeo, jb.url, 'jobicy')) n++; }
  if (n === 0) console.warn('[Job Engine] Jobicy returned no usable jobs (blocked or empty).');
} catch (e) { console.warn('[Job Engine] Jobicy source failed: ' + e.message); }
try {
  const resp = readResp('Fetch Remotive');
  const jobs = Array.isArray(resp.jobs) ? resp.jobs : [];
  let n = 0;
  for (const jb of jobs) { if (pushJob(jb.title, jb.company_name, jb.description, jb.candidate_required_location, jb.url, 'remotive')) n++; }
  if (n === 0) console.warn('[Job Engine] Remotive returned no usable jobs (blocked or empty).');
} catch (e) { console.warn('[Job Engine] Remotive source failed: ' + e.message); }
try {
  const resp = readResp('Fetch Arbeitnow');
  const jobs = Array.isArray(resp.data) ? resp.data : [];
  let n = 0;
  for (const jb of jobs) { if (pushJob(jb.title, jb.company_name, jb.description, jb.location, jb.url, 'arbeitnow')) n++; }
  if (n === 0) console.warn('[Job Engine] Arbeitnow returned no usable jobs (blocked or empty).');
} catch (e) { console.warn('[Job Engine] Arbeitnow source failed: ' + e.message); }
if (out.length === 0) { console.warn('[Job Engine] All extra JSON sources returned no jobs.'); return [{ json: { _extra_empty: true } }]; }
return out;

const stripHtml = (s) => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/\s+/g, ' ').trim();
const normUrl = (u) => String(u || '').trim().split('?')[0].replace(/\/+$/, '').toLowerCase();

const existing = new Set();
try { for (const it of $('Get Existing Jobs').all()) { const u = it.json && it.json.job_url ? normUrl(it.json.job_url) : ''; if (u) existing.add(u); } } catch (e) {}

function parseTitleCompany(raw) {
  const t = String(raw || '').trim();
  let title = t, company = 'Unknown';
  const dashParts = t.split(' - ');
  const atM = t.match(/^(.*?)\s+at\s+(.*?)(?:\s+in\s+.*)?$/i);
  if (dashParts.length >= 2) { title = dashParts[0].trim(); company = dashParts[1].trim(); }
  else if (atM) { title = atM[1].trim(); company = atM[2].trim(); }
  return { title: title || t, company: company || 'Unknown' };
}

const seen = new Set();
const out = [];
function ingestRss(nodeName) {
  try {
    for (const r of $(nodeName).all()) {
      const j = r.json || {};
      const link = j.link || j.guid || '';
      const rawTitle = j.title || '';
      if (!rawTitle || !link) continue;
      const key = normUrl(link);
      if (!key || existing.has(key) || seen.has(key)) continue;
      let desc = stripHtml(j.contentSnippet || j.content || j.summary || j.description || '');
      if (!desc || desc.length < 20) desc = 'Position: ' + rawTitle + '. Full details available via the original listing.';
      const tc = parseTitleCompany(rawTitle);
      seen.add(key);
      out.push({ json: { job_title: tc.title, company: tc.company, job_description: desc, location: 'Saudi Arabia', job_url: link, contact_email: '', status: 'new', job_type: 'general', industry: 'General' } });
    }
  } catch (e) {}
}
function ingestRssMain() {
  try {
    for (const r of $('Fetch RSS').all()) {
      const j = r.json || {};
      const link = j.link || j.guid || '';
      const rawTitle = j.title || '';
      if (!rawTitle || !link) continue;
      const key = normUrl(link);
      if (!key || existing.has(key) || seen.has(key)) continue;
      let desc = stripHtml(j.contentSnippet || j.content || j.summary || j.description || '');
      if (!desc || desc.length < 20) desc = 'Position: ' + rawTitle + '. Full details available via the original listing.';
      const tc = parseTitleCompany(rawTitle);
      seen.add(key);
      out.push({ json: { job_title: tc.title, company: tc.company, job_description: desc, location: 'Saudi Arabia', job_url: link, contact_email: '', status: 'new', job_type: 'general', industry: 'General' } });
    }
  } catch (e) {}
}
ingestRssMain();
try {
  for (const r of $('Fetch Jooble').all()) {
    const resp = r.json || {};
    const jbs = Array.isArray(resp.jobs) ? resp.jobs : [];
    for (const jb of jbs) {
      const link = jb.link || '';
      const rawTitle = jb.title || '';
      if (!rawTitle || !link) continue;
      const key = normUrl(link);
      if (!key || existing.has(key) || seen.has(key)) continue;
      let desc = stripHtml(jb.snippet || '');
      if (!desc || desc.length < 20) desc = 'Position: ' + rawTitle + '. Full details via the original listing.';
      seen.add(key);
      out.push({ json: { job_title: rawTitle, company: String(jb.company || jb.source || 'Unknown').trim(), job_description: desc, location: String(jb.location || 'Saudi Arabia'), job_url: link, contact_email: '', status: 'new', job_type: 'general', industry: 'General' } });
    }
  }
} catch (e) {}
try {
  for (const r of $('Normalize Extra Sources').all()) {
    const jb = r.json || {};
    const link = jb.job_url || '';
    const rawTitle = jb.job_title || '';
    if (!rawTitle || !link) continue;
    const key = normUrl(link);
    if (!key || existing.has(key) || seen.has(key)) continue;
    let desc = stripHtml(jb.job_description || '');
    if (!desc || desc.length < 20) desc = 'Position: ' + rawTitle + '. Full details via the original listing.';
    seen.add(key);
    out.push({ json: { job_title: String(rawTitle).trim(), company: String(jb.company || 'Unknown').trim(), job_description: desc, location: String(jb.location || 'Saudi Arabia'), job_url: link, contact_email: '', status: 'new', job_type: 'general', industry: 'General' } });
  }
} catch (e) {}
ingestRss('Fetch Indeed RSS');
ingestRss('Fetch Bayt');
ingestRss('Fetch Wuzzuf');
return out;

const jobs = $('Merge & Dedup').all().map((i) => i.json || {});
const agencies = $('Get Agencies').all()
  .map((i) => i.json || {})
  .filter((a) => a && a.contact_email && String(a.contact_email).trim())
  .map((a) => ({
    name: String(a.agency_name || 'Agency').trim(),
    email: String(a.contact_email).trim(),
    region: String(a.region || 'Saudi Arabia').trim(),
    specialties: String(a.specialties || '').toLowerCase().split(',').map((s) => s.trim()).filter(Boolean),
    assigned: 0
  }));

const PER_AGENCY_CAP = 3;
const out = [];
for (const j of jobs) {
  if (j.contact_email && String(j.contact_email).trim()) { out.push({ json: j }); continue; }
  const hay = (String(j.job_title || '') + ' ' + String(j.job_description || '')).toLowerCase();
  const matches = [];
  for (const a of agencies) {
    let score = 0;
    for (const sp of a.specialties) { if (sp && hay.includes(sp)) score++; }
    if (score > 0) matches.push({ a, score });
  }
  if (!matches.length) { out.push({ json: j }); continue; }
  const underCap = matches.filter((m) => m.a.assigned < PER_AGENCY_CAP);
  const pool = underCap.length ? underCap : matches;
  pool.sort((x, y) => (y.score - x.score) || (x.a.assigned - y.a.assigned));
  const pick = pool[0].a;
  pick.assigned++;
  out.push({ json: Object.assign({}, j, { contact_email: pick.email, location: j.location || pick.region, job_description: String(j.job_description || '').trim() + ' [via agency: ' + pick.name + ']', status: 'new', job_type: 'general' }) });
}
const real = out.filter((o) => o.json && o.json.job_url);
if (!real.length) return [{ json: { _no_new: true } }];
return real;

const items = $input.all();
const freeProviders = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','protonmail.com','mail.com','yandex.com','gmx.com','ymail.com'];
const vagueKw = ['fast-paced environment','wear many hats','rockstar','ninja','unlimited earning','be your own boss','no experience needed','immediate start','urgent hiring','work from home opportunity','flexible schedule guaranteed'];
const scamKw = ['training fee','equipment purchase','bank details','bank account number','national id','processing fee','registration fee','pay a deposit','western union','send money','upfront payment','activation fee'];
function scoreJob(j){
  const jd = String(j.job_description || '');
  const company = String(j.company || '');
  const email = String(j.contact_email || '').toLowerCase().trim();
  let score = 0;
  let emailDomain = '';
  const at = email.indexOf('@'); if (at !== -1) emailDomain = email.slice(at+1);
  if (emailDomain && freeProviders.indexOf(emailDomain) !== -1) score += 25;
  const words = jd ? jd.split(/\s+/).filter(function(x){return x.length>0;}).length : 0;
  if (words === 0) score += 20; else if (words < 100) score += 15;
  const hay = (jd + ' ' + company).toLowerCase();
  for (let v=0; v<vagueKw.length; v++){ if (hay.indexOf(vagueKw[v]) !== -1) score += 8; }
  for (let k=0; k<scamKw.length; k++){ if (hay.indexOf(scamKw[k]) !== -1) score += 40; }
  if (score > 100) score = 100; if (score < 0) score = 0;
  return score;
}
const out = [];
let kept = 0;
for (const it of items) {
  const j = it.json || {};
  if (j._no_new) { out.push({ json: j }); continue; }
  if (!j.job_url) { continue; }
  const sc = scoreJob(j);
  if (sc >= 40) { console.warn('[Job Engine] Dropped likely ghost/scam job: ' + (j.job_title||'') + ' @ ' + (j.company||'') + ' (scam_score ' + sc + ')'); continue; }
  kept++;
  out.push({ json: Object.assign({}, j, { scam_score: sc }) });
}
if (kept === 0) return [{ json: { _no_new: true } }];
return out;

let jobs = $('Get New Jobs').all().map((i) => i.json || {})
  .filter((j) => j && Object.keys(j).length > 0 && j.contact_email && String(j.contact_email).trim() && j.id !== undefined && j.id !== null);

let rows = [];
try { rows = $('Get Sent Today').all(); } catch (e) { rows = []; }
const now = new Date();
const start = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const end = start + 86400000;
let sentToday = 0;
for (const it of rows) { const r = it.json || {}; if (!r || Object.keys(r).length === 0) continue; const pa = r.processed_at ? Date.parse(r.processed_at) : NaN; if (!isNaN(pa) && pa >= start && pa < end) sentToday++; }

const DAILY = 40;
const remaining = Math.max(0, DAILY - sentToday);
let mr;
try { mr = $('Manual Run').first().json.max_sends; } catch (e) {}
if (mr === undefined || mr === null) { try { const s = $('Schedule Daily 8AM').first().json.max_sends; if (s !== undefined) mr = s; } catch (e) {} }
let maxRun = DAILY;
if (mr !== undefined && mr !== null && String(mr).length) { const p = parseInt(String(mr), 10); if (!isNaN(p)) maxRun = p; }
const cap = Math.min(remaining, maxRun, jobs.length);
return jobs.slice(0, cap).map((j) => ({ json: j }));

let processed = 0;
try { processed = $('Cap Sends (40/day)').all().length; } catch (e) {}
const date = new Date().toISOString().slice(0,10);
const msg = '\u2705 Automated Job Applier run complete (' + date + '). Jobs processed this run: ' + processed + '.';
return [{ json: { chat_id: '8890901423', message: msg } }];

var kimi = $json || {};
var row = {};
try { row = $('Loop Over Jobs').item.json || {}; } catch (e) { row = {}; }
var status = String(kimi.status || '').toLowerCase();
var isSent = status === 'sent';
var jobTitle = String(row.job_title || kimi.job_title || 'Position').trim();
var company = String(kimi.company || row.company || 'the company').trim();
var fit = null;
if (row.fit_score !== undefined && row.fit_score !== null && String(row.fit_score).length && Number(row.fit_score) > 0) { fit = Number(row.fit_score); }
else if (row.adjusted_fit_score !== undefined && row.adjusted_fit_score !== null && Number(row.adjusted_fit_score) > 0) { fit = Number(row.adjusted_fit_score); }
else { var sc = Number(row.scam_score); if (isNaN(sc)) sc = 0; fit = Math.max(40, 100 - sc); }
fit = Math.round(fit);
var text = '\u2705 Applied: ' + jobTitle + ' at ' + company + ' \u2013 Fit: ' + fit + '%';
return [{ json: { is_sent: isSent, status: status, applied_text: text, chat_id: '8890901423', row_id: kimi.row_id, company: company, job_title: jobTitle, fit_score: fit } }];

const rows = $('Get New Jobs').all().map((i) => i.json || {});
const out = [];
for (const r of rows) {
  if (!r || Object.keys(r).length === 0) continue;
  if (r.id === undefined || r.id === null) continue;
  const email = (r.contact_email || '').toString().trim();
  if (!email) out.push({ json: { id: r.id } });
}
return out;
